    for raw in value:
        if not isinstance(raw, dict):
            continue
        start = _finite_nonnegative(raw.get("start_time"))
        end = _finite_nonnegative(raw.get("end_time"))
        title = str(raw.get("title") or "").strip()[:300]
        if start is None or end is None or end < start:
