    return Path(str(candidate))


def history_output_type(record: dict[str, Any]) -> str:
    raw = str(record.get("vodforge_output_type") or "").strip().upper()
    if raw == "ORIGINAL AUDIO":
        return "Original audio"
    if raw in {"MP4", "MP3"}:
