    try:
        pending_history_path(path).unlink()
    except OSError as exc:
        # Fail closed before accepting further history edits. Retaining this
        # idempotent journal permits a retry without losing either update.
        raise HistoryError(
            "Pending history was saved but recovery cleanup failed.",
            document="pending",
            phase="retire",
        ) from exc
    return result, len(operations)


def load_history(
    path: Path, *, on_recovered: Callable[[int], None] | None = None
) -> list[dict[str, Any]]:
    records = _load_history_records(path)
    try:
        pending_file_work = file_operations_pending(path)
    except (OSError, ValueError) as exc:
        raise HistoryError(
            "File recovery needs attention before Library changes.",
            document="main",
            phase="read",
        ) from exc
    # Browsing/playback can use the actual committed ledger while recovery is
    # pending. Durable incoming deltas remain staged until file work is settled.
    if pending_file_work:
        return records
    records, count = recover_pending_history(path, records)
    if count and on_recovered is not None:
        try:
            on_recovered(count)
        except Exception:  # noqa: BLE001, S110  # nosec B110 - optional observation cannot prevent durable recovery
            pass
    return records


