def _finite_nonnegative(value: Any) -> float | None:
    try:
        number = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return number if math.isfinite(number) and number >= 0 else None


def sanitize_chapters(value: Any) -> list[dict[str, Any]]:
    """Retain bounded, display-only chapter timing from provider metadata."""

    if not isinstance(value, list):
        return []
    result: list[dict[str, Any]] = []
    for raw in value:
        if not isinstance(raw, dict):
            continue
        start = _finite_nonnegative(raw.get("start_time"))
        end = _finite_nonnegative(raw.get("end_time"))
        title = str(raw.get("title") or "").strip()[:300]
        if start is None or end is None or end < start:
            continue
        result.append({"start_time": start, "end_time": end, "title": title})
        if len(result) >= MAX_CHAPTERS:
            break
    return result


def sanitize_heatmap(value: Any) -> list[dict[str, float]]:
    """Retain bounded YouTube engagement samples without provider URLs."""

    if not isinstance(value, list):
        return []
    result: list[dict[str, float]] = []
    for raw in value:
        if not isinstance(raw, dict):
            continue
        start = _finite_nonnegative(raw.get("start_time"))
        end = _finite_nonnegative(raw.get("end_time"))
        raw_value = raw.get("value")
        if raw_value is None:
            continue
        try:
            value_number = float(raw_value)
        except (TypeError, ValueError, OverflowError):
            continue
        if (
            start is None
            or end is None
            or end < start
            or not math.isfinite(value_number)
        ):
            continue
        result.append(
            {
                "start_time": start,
                "end_time": end,
                "value": min(1.0, max(0.0, value_number)),
            }
        )
        if len(result) >= MAX_HEATMAP_POINTS:
            break
    return result


class HistoryError(RuntimeError):
    """Local message plus observed, closed-vocabulary history failure facts."""

    def __init__(
        self,
        message: str,
        *,
        document: str = "unknown",
        phase: str = "unknown",
        cause: str = "unknown",
    ) -> None:
        super().__init__(message)
        self.document = document if document in {"main", "pending"} else "unknown"
        self.phase = (
            phase
            if phase in {"read", "parse", "validate", "write", "retire"}
            else "unknown"
        )
        self.cause = (
            cause
            if cause
            in {
                "malformed_json",
                "unsupported_schema",
                "invalid_structure",
