                    result.append((key, None, None))
                    continue
                try:
                    size, backdrop, radius = requested_specs.get(
                        key, (requested_size, "", 8)
                    )
                    asset = (
                        source_path(
                            record, size, requested_roles.get(key, "media"), cancelled
                        )
                        if source_path is not None
